/* Series colors: validated categorical slots 1–2 (blue, orange), stepped per theme.
   Chrome (surface, text, grid) comes from Gravity UI tokens, so it follows the app theme. */
.tlc {
  --tlc-surface: var(--g-color-base-background);
  --tlc-text: var(--g-color-text-primary);
  --tlc-text-2: var(--g-color-text-secondary);
  --tlc-muted: var(--g-color-text-hint);
  --tlc-grid: var(--g-color-line-generic);
  --tlc-axis: var(--g-color-line-generic-hover, var(--g-color-line-generic));
  --tlc-series-1: #2a78d6;
  --tlc-series-2: #eb6834;

  position: relative;
  margin: 0;
  padding: 16px;
  background: var(--tlc-surface);
  color: var(--tlc-text);
  border: 1px solid var(--g-color-line-generic);
  border-radius: 12px;
  font-family: var(--g-font-family-sans, system-ui, sans-serif);
}
.tlc[data-theme='dark'] {
  --tlc-series-1: #3987e5;
  --tlc-series-2: #d95926;
}

.tlc__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}
.tlc__title {
  font-size: 15px;
  font-weight: 600;
}
.tlc__toggle {
  font: inherit;
  font-size: 13px;
  color: var(--tlc-text-2);
  background: none;
  border: 1px solid var(--tlc-grid);
  border-radius: 6px;
  padding: 2px 10px;
  cursor: pointer;
}
.tlc__toggle:hover {
  background: var(--g-color-base-simple-hover);
}

.tlc__legend {
  display: flex;
  gap: 16px;
  margin: 0 0 8px;
  padding: 0;
  list-style: none;
  font-size: 13px;
  color: var(--tlc-text-2);
}
.tlc__legend li {
  display: flex;
  align-items: center;
  gap: 6px;
}
.tlc__key {
  width: 12px;
  height: 2px;
  border-radius: 1px;
}

.tlc__plot {
  position: relative;
}
.tlc__grid {
  stroke: var(--tlc-grid);
  stroke-width: 1;
}
.tlc__axis {
  stroke: var(--tlc-axis);
  stroke-width: 1;
}
.tlc__cross {
  stroke: var(--tlc-muted);
  stroke-width: 1;
}
.tlc__tick {
  fill: var(--tlc-muted);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
.tlc__line {
  fill: none;
  stroke-width: 2;
  stroke-linejoin: round;
  stroke-linecap: round;
}
.tlc__dot {
  stroke: var(--tlc-surface);
  stroke-width: 2;
}

.tlc__tip {
  position: absolute;
  top: 8px;
  pointer-events: none;
  padding: 8px 10px;
  font-size: 13px;
  white-space: nowrap;
  background: var(--g-color-base-float, var(--tlc-surface));
  border: 1px solid var(--tlc-grid);
  border-radius: 8px;
  box-shadow: 0 4px 16px var(--g-color-sfx-shadow, rgba(0, 0, 0, 0.15));
}
.tlc__tipcat {
  color: var(--tlc-text-2);
  margin-bottom: 4px;
}
.tlc__tiprow {
  display: flex;
  align-items: center;
  gap: 6px;
}
.tlc__tipkey {
  width: 10px;
  height: 2px;
  border-radius: 1px;
}
.tlc__tipname {
  color: var(--tlc-text-2);
}

.tlc__tablewrap {
  overflow: auto;
}
.tlc__table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}
.tlc__table th,
.tlc__table td {
  padding: 6px 8px;
  text-align: right;
  border-bottom: 1px solid var(--tlc-grid);
}
.tlc__table th:first-child {
  text-align: left;
  font-weight: 400;
  color: var(--tlc-text-2);
}
.tlc__table thead th {
  color: var(--tlc-text-2);
  font-weight: 600;
}

